import math
import os
from typing import List

from openai import OpenAI


def _cosine_similarity(vec1: List[float], vec2: List[float]) -> float:
    if len(vec1) != len(vec2):
        raise ValueError("Embedding vectors must have the same length.")
    dot_product = sum(a * b for a, b in zip(vec1, vec2))
    norm1 = math.sqrt(sum(a * a for a in vec1))
    norm2 = math.sqrt(sum(b * b for b in vec2))
    if norm1 == 0.0 or norm2 == 0.0:
        raise ValueError("Cannot compute cosine similarity for zero-vector embeddings.")
    return dot_product / (norm1 * norm2)


def cosine_similarity_between_texts(text1: str, text2: str, model: str = "text-embedding-3-small") -> float:
    client = OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))
    response = client.embeddings.create(
        model=model,
        input=[text1, text2],
    )
    embeddings = [item.embedding for item in response.data]
    return _cosine_similarity(embeddings[0], embeddings[1])
